actions.command:
cd "$INPUT" || exit 1
rm=
if [[ -f package.json ]]; then
  if [[ -f pnpm-lock.yaml ]]; then i=(pnpm install --frozen-lockfile)
  elif [[ -f yarn.lock ]]; then if [[ $(yarn --version 2>/dev/null) == 1.* ]]; then i=(yarn install --frozen-lockfile); else i=(yarn install --immutable); fi
  elif [[ -f bun.lock || -f bun.lockb ]]; then i=(bun install --frozen-lockfile)
  elif [[ -f package-lock.json ]]; then i=(npm ci)
  else echo 'package.json has no lockfile to install from' >&2; exit 1; fi
  rm=node_modules
elif [[ -f Podfile.lock ]]; then i=(pod install); rm=Pods
elif [[ -f Gemfile.lock ]]; then i=(bundle install)
else echo 'No lockfile found (npm, pnpm, yarn, bun, Podfile.lock, Gemfile.lock)' >&2; exit 1; fi
command -v ${i[1]} >/dev/null || { echo "${i[1]} is not installed" >&2; exit 1; }
MSG="Delete ${rm:-nothing} and run: ${i[*]}"$'\n'"in ${INPUT:t}?" osascript -e 'display dialog (system attribute "MSG") buttons {"Cancel","Reinstall"} default button "Cancel" cancel button "Cancel" with icon caution with title "FlickWheel"' >/dev/null || { echo Cancelled >&2; exit 1; }
[[ -z $rm ]] || rm -rf -- "$rm"
"${i[@]}"
